; Stop of sprites 0-4
; $8604-$8618

; Stops the animation and the path of sprite 4 and clears the bits of sprites 0-4 in sprite_enable_shadow. The loop loads A again, so sprites 3-0 get the new sprite_enable_shadow value as animation and path, not 0.
hide_sprites_0_to_4
        ldx #$04
        lda #$00
hide_sprites_0_to_4_loop
        sta sprite_anim,x
        sta sprite_path,x
        lda sprite_enable_shadow
        and bit_masks_inverted,x
        sta sprite_enable_shadow
        dex
        bpl hide_sprites_0_to_4_loop
        rts
